export const MEMSTREAM_SCHEMA_SQL = "-- Memstream platform DB\n-- Source of truth for platform schema. Apply with:\n--\n--   make setup-db\n--\n-- Application live-memory tables (agent_memory_chunks) are NOT here —\n-- Memstream Enable applies sql/application.sql on the Connect DB.\n--\n--   CREATE DATABASE IF NOT EXISTS memstream\n\nCREATE TABLE IF NOT EXISTS memstream_connections (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  name STRING NOT NULL DEFAULT 'default',\n  -- AES-256-GCM: iv (12) || tag (16) || ciphertext\n  database_url_ciphertext BYTES NOT NULL,\n  database_label STRING,\n  bucket STRING,\n  region STRING,\n  prefix STRING,\n  is_active BOOL NOT NULL DEFAULT true,\n  -- SaaS org (nullable until auth); connection id is the workspace id\n  org_id STRING,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  INDEX memstream_connections_active_idx (is_active)\n);\n\n-- Safe for clusters created before org_id existed\nALTER TABLE memstream_connections ADD COLUMN IF NOT EXISTS org_id STRING;\n\nCREATE TABLE IF NOT EXISTS memstream_runs (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  status STRING NOT NULL,\n  profile_path STRING NOT NULL,\n  tables STRING NOT NULL,\n  bucket STRING,\n  region STRING,\n  prefix STRING,\n  stack_name STRING,\n  shop_url STRING,\n  job_id STRING,\n  app_database_label STRING,\n  -- Workspace id (= memstream_connections.id)\n  connection_id UUID,\n  log STRING[] NOT NULL DEFAULT ARRAY[],\n  -- JSON array of enable JobStep objects (durable progress)\n  steps_json STRING,\n  error STRING,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  finished_at TIMESTAMPTZ,\n  INDEX memstream_runs_created_idx (created_at DESC),\n  INDEX memstream_runs_job_idx (job_id)\n);\n\n-- Safe for clusters created before connection_id / steps_json existed\nALTER TABLE memstream_runs ADD COLUMN IF NOT EXISTS connection_id UUID;\nALTER TABLE memstream_runs ADD COLUMN IF NOT EXISTS steps_json STRING;\n\nCREATE TABLE IF NOT EXISTS memstream_cdc_keys (\n  scope_id STRING NOT NULL,\n  object_key STRING NOT NULL,\n  processed_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  PRIMARY KEY (scope_id, object_key)\n);\n\n-- Memory profiles (YAML). Seeded from profiles/*.yaml; console saves here so\n-- EC2/Lambda do not depend on the local filesystem for rules.\nCREATE TABLE IF NOT EXISTS memstream_profiles (\n  id STRING PRIMARY KEY,\n  yaml STRING NOT NULL,\n  application STRING NOT NULL DEFAULT '',\n  source STRING NOT NULL DEFAULT 'builtin', -- builtin | user\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Prior YAML for each profile save (restore / audit). Current row stays in memstream_profiles.\nCREATE TABLE IF NOT EXISTS memstream_profile_versions (\n  profile_id STRING NOT NULL,\n  version INT NOT NULL,\n  yaml STRING NOT NULL,\n  application STRING NOT NULL DEFAULT '',\n  source STRING NOT NULL DEFAULT 'user',\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  PRIMARY KEY (profile_id, version),\n  INDEX memstream_profile_versions_created_idx (profile_id, created_at DESC)\n);\n\n-- Thin SaaS orgs (no full auth yet). Workspaces (= connections) optionally belong to an org.\nCREATE TABLE IF NOT EXISTS memstream_orgs (\n  id STRING PRIMARY KEY,\n  name STRING NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Shareable invite codes to join an org (single-use until redeemed or expired).\nCREATE TABLE IF NOT EXISTS memstream_org_invites (\n  code STRING PRIMARY KEY,\n  org_id STRING NOT NULL,\n  label STRING,\n  expires_at TIMESTAMPTZ,\n  redeemed_at TIMESTAMPTZ,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  INDEX memstream_org_invites_org_idx (org_id)\n);\n\n-- Console operators (demo login). Password stored as scrypt$saltHex$hashHex.\nCREATE TABLE IF NOT EXISTS memstream_operators (\n  username STRING PRIMARY KEY,\n  password_hash STRING NOT NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n" as const;

export const APPLICATION_SCHEMA_SQL = "-- Application DB (Connect URL) — applied by Memstream Enable on the connected app DB.\n-- Not applied by make setup-db (that only migrates the Memstream platform DB).\n--\n-- Includes demo shop tables + agent_memory_chunks (VECTOR) for live memory.\n-- If VECTOR INDEX fails, Enable retries with sql/vector_index.sql settings.\n\nSET CLUSTER SETTING feature.vector_index.enabled = true;\n\n-- Demo app tables -----------------------------------------------------------\n\nCREATE TABLE IF NOT EXISTS customers (\n  id STRING PRIMARY KEY,\n  name STRING NOT NULL\n);\n\nCREATE TABLE IF NOT EXISTS orders (\n  id STRING PRIMARY KEY,\n  customer_id STRING NOT NULL REFERENCES customers (id),\n  status STRING NOT NULL,\n  note STRING NULL,\n  sku STRING NULL,\n  quantity INT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Existing clusters created before sku/quantity existed\nALTER TABLE orders ADD COLUMN IF NOT EXISTS sku STRING NULL;\nALTER TABLE orders ADD COLUMN IF NOT EXISTS quantity INT NULL;\n\nCREATE TABLE IF NOT EXISTS stock (\n  sku STRING PRIMARY KEY,\n  warehouse_id STRING NOT NULL,\n  quantity INT NOT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\nCREATE TABLE IF NOT EXISTS tickets (\n  id STRING PRIMARY KEY,\n  order_id STRING NULL REFERENCES orders (id),\n  status STRING NOT NULL,\n  body STRING NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Support / staff agent handoffs (written by /api/shop/ask → Memstream chunks)\nCREATE TABLE IF NOT EXISTS case_notes (\n  id STRING PRIMARY KEY,\n  order_id STRING NULL REFERENCES orders (id),\n  ticket_id STRING NULL,\n  author STRING NOT NULL,\n  body STRING NOT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- saas-security profile\nCREATE TABLE IF NOT EXISTS users (\n  id STRING PRIMARY KEY,\n  org_id STRING NOT NULL,\n  email STRING NOT NULL,\n  role STRING NOT NULL,\n  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()\n);\n\n-- Live memory (embeddings stay on the application DB) -----------------------\n\nCREATE TABLE IF NOT EXISTS agent_memory_chunks (\n  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),\n  application STRING NOT NULL,\n  -- Memstream connection that produced this chunk (scopes multi-app DBs)\n  connection_id UUID,\n  table_name STRING NOT NULL,\n  rule_name STRING NOT NULL,\n  tags STRING[] NOT NULL DEFAULT ARRAY[],\n  body STRING NOT NULL,\n  embedding VECTOR(1024),\n  source_ts TIMESTAMPTZ NULL,\n  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),\n  INDEX agent_memory_chunks_app_idx (application, created_at DESC),\n  INDEX agent_memory_chunks_connection_idx (connection_id, created_at DESC)\n);\n\n-- Safe for clusters created before connection_id existed\nALTER TABLE agent_memory_chunks ADD COLUMN IF NOT EXISTS connection_id UUID;\nCREATE INDEX IF NOT EXISTS agent_memory_chunks_connection_idx\n  ON agent_memory_chunks (connection_id, created_at DESC);\n\n-- Vector index (separate statement — Enable retries with declarative changer if needed)\nCREATE VECTOR INDEX IF NOT EXISTS agent_memory_chunks_embedding_idx\n  ON agent_memory_chunks (embedding vector_cosine_ops);\n\n-- Demo seed (idempotent) ----------------------------------------------------\n\nINSERT INTO customers (id, name) VALUES\n  ('c1', 'Alex'),\n  ('c2', 'Sam')\nON CONFLICT (id) DO NOTHING;\n\nUPDATE customers SET name = 'Alex' WHERE id = 'c1' AND name IN ('Acme', 'c1');\nUPDATE customers SET name = 'Sam' WHERE id = 'c2' AND name IN ('Globex', 'c2');\n\nINSERT INTO orders (id, customer_id, status, sku, quantity) VALUES\n  ('90', 'c1', 'shipped', 'SKU-12', 1),\n  ('100', 'c1', 'pending', 'SKU-12', 1),\n  ('101', 'c2', 'pending', 'SKU-99', 1)\nON CONFLICT (id) DO NOTHING;\n\nUPDATE orders SET note = 'Shipped 1× SKU-12 for Alex (c1)'\nWHERE id = '90' AND (note IS NULL OR note = '' OR note = 'Shipped 1× SKU-12 for Alex');\n\nINSERT INTO tickets (id, order_id, status, body) VALUES\n  (\n    't-90',\n    '90',\n    'closed',\n    'Alex (c1) reported late delivery on Field Lamp order 90 after asking for weekend delivery since they''re away on weekdays; shipping credit issued and case closed.'\n  )\nON CONFLICT (id) DO NOTHING;\n\nINSERT INTO case_notes (id, order_id, ticket_id, author, body) VALUES\n  (\n    'n-89',\n    '90',\n    't-90',\n    'staff',\n    'Alex (c1) mentioned they''re away Monday-Friday for work and can only receive or hand off packages on weekends; that''s why the order 90 redelivery moved to Saturday. Noting for future scheduling.'\n  ),\n  (\n    'n-90',\n    '90',\n    't-90',\n    'staff',\n    'Follow-up with Alex (c1) on late Field Lamp order 90 — shipping credit issued; case closed. Resume only if a new ticket opens.'\n  )\nON CONFLICT (id) DO NOTHING;\n\nINSERT INTO stock (sku, warehouse_id, quantity) VALUES\n  ('SKU-12', 'east', 40),\n  ('SKU-99', 'west', 10)\nON CONFLICT (sku) DO NOTHING;\n\nINSERT INTO users (id, org_id, email, role) VALUES\n  ('u1', 'org-acme', 'admin@acme.test', 'member'),\n  ('u2', 'org-acme', 'boss@acme.test', 'owner')\nON CONFLICT (id) DO NOTHING;\n" as const;
